/** Isolated bounded fixture: real client GUI/inspection/attack packets, saved dedicated restart. */
public final class ContractReliabilityNetworkServer implements ModInitializer {
 private Path dir;private int phase,ticks;private long nonce=System.currentTimeMillis();private final long[] sent=new long[2];private final String[] names={"WBOne","WBTwo"};private final UUID[] ids=new UUID[2];private UUID broken,normal,target;private BlockPos board;private long paid;private double maximum;private final Map<String,Object> results=new LinkedHashMap<>();
 private void check(boolean value,String message){if(!value)throw new IllegalStateException(message);}
 private void write(String name,Object value)throws Exception{Files.writeString(dir.resolve(name),new GsonBuilder().setPrettyPrinting().create().toJson(value));}
 private JsonObject read(String name)throws Exception{return JsonParser.parseString(Files.readString(dir.resolve(name))).getAsJsonObject();}
 private void command(int index,String action,Object...args)throws Exception{var j=new JsonObject();j.addProperty("nonce",++nonce);sent[index]=nonce;j.addProperty("action",action);for(int a=0;a<args.length;a+=2)j.addProperty(args[a].toString(),args[a+1].toString());write(names[index]+".command.json",j);}
 private boolean ack(int i)throws Exception{var f=dir.resolve(names[i]+".reply.json");return Files.exists(f)&&read(names[i]+".reply.json").get("nonce").getAsLong()==sent[i];}
 private ContractInstance hunt(MinecraftServer s,int i){return ContractState.get(s).find(ids[i]);}
 private long wallet(ServerPlayerEntity p){return WalletTransactions.balance(p.getInventory().getStack(8));}
 private void open(ServerPlayerEntity p){p.closeHandledScreen();p.teleport(p.getServerWorld(),board.getX()+.5,board.getY(),board.getZ()-2.5,0,0);p.getServerWorld().getBlockState(board).onUse(p.getServerWorld(),p,new BlockHitResult(board.toCenterPos(),Direction.NORTH,board,false));}
 private void setup(MinecraftServer s,ServerPlayerEntity a,ServerPlayerEntity b){var w=s.getOverworld();for(int x=-1;x<=8;x++)for(int z=-1;z<=8;z++)w.getChunk(x,z);var forest=w.getRegistryManager().get(RegistryKeys.BIOME).getEntry(net.minecraft.world.biome.BiomeKeys.FOREST).orElseThrow();for(int x=-1;x<=8;x++)for(int z=-1;z<=8;z++)w.getChunk(x,z).populateBiomes((i,j,k,n)->forest,w.getChunkManager().getNoiseConfig().getMultiNoiseSampler());for(int x=0;x<=128;x++)for(int z=0;z<=128;z++){w.setBlockState(new BlockPos(x,128,z),Blocks.GRASS_BLOCK.getDefaultState(),2);for(int y=129;y<=141;y++){var at=new BlockPos(x,y,z);if(!w.getBlockState(at).isAir())w.setBlockState(at,Blocks.AIR.getDefaultState(),2);}}
  w.setTimeOfDay(50L*24000+18000);w.getGameRules().get(net.minecraft.world.GameRules.DO_DAYLIGHT_CYCLE).set(false,s);board=new BlockPos(20,129,32);check(NoticeBoardBlock.place(w,board,Direction.NORTH),"Board fixture placement");var pool=List.of("katakan","ghoul","foglet","endrega","fiend").stream().map(k->ProceduralHunts.id(k).toString()).toList();VillageOffers.get(s).personal(VillageOffers.identity(w,board),a.getUuid(),w.getTime(),pool);
  for(var p:List.of(a,b)){p.changeGameMode(GameMode.CREATIVE);p.setInvulnerable(true);p.setNoGravity(true);p.getInventory().clear();p.getInventory().setStack(8,new ItemStack(com.witchersbestiary.economy.Currency.WALLET));p.getInventory().selectedSlot=0;p.getInventory().setStack(0,new ItemStack(Items.NETHERITE_SWORD));p.getAttributeInstance(EntityAttributes.GENERIC_ATTACK_DAMAGE).setBaseValue(1000);p.setExperienceLevel(p==a?5:50);open(p);}
 }
 private ContractInstance broken(ServerPlayerEntity p){var profile=ProceduralProfile.generate(215,"katakan");var c=new ContractInstance(UUID.randomUUID(),p.getUuid(),CrownRewards.fresh(ProceduralHunts.snapshot(Contracts.DEFINITIONS.find(ProceduralHunts.id("katakan")),profile)),System.currentTimeMillis());c.procedural=profile;c.transition(ContractInstance.Status.ACCEPTED);c.hunt=new SwampHunt(p.getServerWorld().getRegistryKey().getValue().toString(),p.getBlockPos());c.hunt.status=SwampHunt.Status.WAITING;c.investigation=new ContractInvestigation(c.id(),p.getUuid(),c.hunt.dimension);var restored=ContractInstance.fromNbt(c.toNbt());ContractState.get(p.getServer()).add(restored);Investigations.accepted(p,restored);return restored;}
 public void onInitialize(){if(!Boolean.getBoolean("witchersbestiary.contractReliabilityNetwork"))return;dir=Path.of(System.getProperty("witchersbestiary.stage20eOutput"));boolean resume=Files.exists(dir.resolve("reliability-resume.json"));phase=Boolean.getBoolean("witchersbestiary.contractReliabilityReview")?200:resume?100:0;ServerTickEvents.END_SERVER_TICK.register(s->{try{if(phase==999)return;if(phase==13){if(!ack(0)||!ack(1))return;for(int i=0;i<2;i++)command(i,"wait");s.getPlayerManager().saveAllPlayerData();s.save(false,true,true);phase=999;s.stop(false);return;}if(++ticks>14000)throw new IllegalStateException("Bounded contract reliability timeout, phase"+phase);var a=s.getPlayerManager().getPlayer(names[0]);var b=s.getPlayerManager().getPlayer(names[1]);if(a==null||b==null)return;var players=List.of(a,b);
  switch(phase){
   case 200->{board=new BlockPos(20,129,32);s.getOverworld().getChunk(board.getX()>>4,board.getZ()>>4);check(wallet(a)>0&&wallet(a)==wallet(b),"Both paid wallets survived the saved world reload");results.put("both_native_wallets_reloaded",true);var stuck=broken(a);broken=stuck.id();open(a);command(0,"cancelPrompt","definition",ProceduralHunts.id("katakan"),"instance",broken);b.closeHandledScreen();b.teleport(s.getOverworld(),20,129,30,0,0);var fresh=Contracts.assignPrepared(b,ProceduralHunts.id("katakan"),215L);ids[1]=fresh.id();b.teleport(s.getOverworld(),-220,129,-220,0,0);command(1,"trackingProof");phase=201;}
   case 201->{if(!ack(0)||!ack(1))return;check(ContractState.get(s).find(broken).status()==ContractInstance.Status.ACCEPTED,"Modal is only confirmation");check(read(names[1]+".reply.json").getAsJsonObject("snapshot").has("area"),"Visible persistent HUD beyond150 blocks");results.put("visible_far_hud",true);command(0,"cancelConfirm");b.teleport(s.getWorld(net.minecraft.world.World.NETHER),0,100,0,0,0);command(1,"dimension","dimension","minecraft:the_nether");phase=202;}
   case 202->{if(!ack(0)||!ack(1))return;check(ContractState.get(s).find(broken).status()==ContractInstance.Status.CANCELLED,"Reviewed modal confirms exact instance");var snap=read(names[1]+".reply.json").getAsJsonObject("snapshot");check(snap.get("hint").getAsString().equals("dimension")&&!snap.has("area"),"Visible other-dimension HUD");results.put("visible_confirmation_and_dimension_hud",true);results.put("review_only",true);results.put("complete",true);write("complete.json",results);for(int i=0;i<2;i++)command(i,"stop");phase=999;}
   case 0->{setup(s,a,b);for(int i=0;i<2;i++)command(i,"accept","definition",ProceduralHunts.id("katakan"));phase=1;}
   case 1->{if(!ack(0)||!ack(1))return;for(int i=0;i<2;i++){var c=ContractState.get(s).ownedBy(players.get(i).getUuid()).stream().filter(v->v.status()==ContractInstance.Status.ACCEPTED).findFirst().orElseThrow();ids[i]=c.id();check(c.investigation.clues.size()==2&&c.investigation.routeVersion==3&&Investigations.view(players.get(i)).has("area"),"Immediate complete route and HUD coordinates");double gap=c.investigation.clues.get(0).position.toCenterPos().subtract(c.investigation.clues.get(1).position.toCenterPos()).horizontalLength();check(gap>=40&&gap<=60,"Clue gap40..60");}check(!hunt(s,0).investigation.next().id.equals(hunt(s,1).investigation.next().id),"Private clue identities");results.put("immediate_hud_and_two_private_routes",true);a.teleport(s.getOverworld(),250,129,250,0,0);command(0,"trackingProof");command(1,"wait");phase=2;}
   case 2->{if(!ack(0))return;check(read(names[0]+".reply.json").getAsJsonObject("snapshot").has("area"),"Far HUD coordinates survive beyond150 blocks");results.put("far_hud",true);a.teleport(s.getWorld(net.minecraft.world.World.NETHER),0,100,0,0,0);command(0,"dimension","dimension","minecraft:the_nether");phase=3;}
   case 3->{if(!ack(0))return;var snap=read(names[0]+".reply.json").getAsJsonObject("snapshot");check(snap.get("hint").getAsString().equals("dimension")&&!snap.has("area")&&snap.get("target_dimension").getAsString().equals("minecraft:overworld"),"Cross-dimension tracking without false coordinates");results.put("dimension_hud",true);for(int i=0;i<2;i++){var p=players.get(i);var at=hunt(s,i).investigation.clues.getFirst().position;p.teleport(s.getOverworld(),at.getX()+.5,at.getY(),at.getZ()+1,0,0);command(i,"study","progress",1);}phase=4;}
   case 4->{if(!ack(0)||!ack(1))return;for(int i=0;i<2;i++){check(hunt(s,i).investigation.current==1,"First clue studied");var at=hunt(s,i).investigation.clues.getLast().position;players.get(i).teleport(s.getOverworld(),at.getX()+.5,at.getY(),at.getZ()+1,0,0);command(i,"study","progress",2);}phase=5;}
   case 5->{if(!ack(0)||!ack(1))return;for(int i=0;i<2;i++){check(hunt(s,i).investigation.stage==ContractInvestigation.Stage.LAIR_FOUND,"Second clue reveals lair only");var at=hunt(s,i).investigation.lair;players.get(i).teleport(s.getOverworld(),at.getX()+.5,at.getY(),at.getZ()-2,0,0);command(i,"wait");}phase=6;}
   case 6->{if(hunt(s,0).hunt.target==null||hunt(s,1).hunt.target==null)return;for(int i=0;i<2;i++){var mob=(MobEntity)s.getOverworld().getEntity(hunt(s,i).hunt.target);if(mob==null)return;mob.setAiDisabled(true);check(ProgressiveDifficulty.steps(mob)==2,"Both personal targets use global phase2 regardless of XP");}check(!hunt(s,0).hunt.target.equals(hunt(s,1).hunt.target),"Unique targets with collision-safe fallback");results.put("two_clients_two_clues_lairs_and_unique_scaled_targets",true);var mob=s.getOverworld().getEntity(hunt(s,0).hunt.target);a.teleport(s.getOverworld(),mob.getX()-2,mob.getY(),mob.getZ(),-90,0);command(0,"fight","target",mob.getUuid());phase=7;}
   case 7->{if(!ack(0)||hunt(s,0).status()!=ContractInstance.Status.COMPLETED)return;open(a);command(0,"claim","definition",ProceduralHunts.id("katakan"));phase=8;}
   case 8->{if(!ack(0)||hunt(s,0).status()!=ContractInstance.Status.REWARDED)return;paid=wallet(a);check(paid>0&&wallet(b)==0,"Actual client kill and crowns only for owner");var stuck=broken(a);broken=stuck.id();open(a);command(0,"cancelPrompt","definition",ProceduralHunts.id("katakan"),"instance",broken);phase=9;}
   case 9->{if(!ack(0))return;check(ContractState.get(s).find(broken).status()==ContractInstance.Status.ACCEPTED,"Opening confirmation cannot cancel");command(0,"cancelBack");phase=10;}
   case 10->{if(!ack(0))return;check(ContractState.get(s).find(broken).status()==ContractInstance.Status.ACCEPTED,"Back leaves contract unchanged");command(0,"cancelPrompt","definition",ProceduralHunts.id("katakan"),"instance",broken);phase=11;}
   case 11->{if(!ack(0))return;command(0,"cancelConfirm");phase=12;}
   case 12->{if(!ack(0))return;check(ContractState.get(s).find(broken).status()==ContractInstance.Status.CANCELLED&&wallet(a)==paid&&hunt(s,1).status()==ContractInstance.Status.ACCEPTED,"Confirmed broken-contract cancellation is owner scoped and unpaid");results.put("broken_gui_confirmation_back_and_cancel",true);target=hunt(s,1).hunt.target;maximum=((MobEntity)s.getOverworld().getEntity(target)).getMaxHealth();write("reliability-resume.json",Map.of("a",ids[0],"b",ids[1],"broken",broken,"target",target,"max",maximum,"paid",paid,"board",board.asLong()));write("reliability-results.json",results);write("resume.json",Map.of("contractReliability",true));for(int i=0;i<2;i++)command(i,"disconnect");phase=13;}
   case 13->{if(!ack(0)||!ack(1))return;s.getPlayerManager().saveAllPlayerData();s.save(false,true,true);phase=999;s.stop(false);}
   case 100->{if(Files.exists(dir.resolve("reliability-results.json")))for(var entry:read("reliability-results.json").entrySet())results.put(entry.getKey(),entry.getValue());var r=read("reliability-resume.json");ids[0]=UUID.fromString(r.get("a").getAsString());ids[1]=UUID.fromString(r.get("b").getAsString());broken=UUID.fromString(r.get("broken").getAsString());target=UUID.fromString(r.get("target").getAsString());board=BlockPos.fromLong(r.get("board").getAsLong());paid=r.get("paid").getAsLong();maximum=r.get("max").getAsDouble();s.getOverworld().setTimeOfDay(100L*24000+18000);var at=hunt(s,1).hunt.position;s.getOverworld().getChunk(at.getX()>>4,at.getZ()>>4);var mob=(MobEntity)s.getOverworld().getEntity(target);if(mob==null)return;check(hunt(s,0).status()==ContractInstance.Status.REWARDED&&wallet(a)==paid&&ContractState.get(s).find(broken).status()==ContractInstance.Status.CANCELLED,"Saved reward and cancellation survive JVM restart");check(mob.getMaxHealth()==maximum&&ProgressiveDifficulty.steps(mob)==2,"Existing target does not rescale on later calendar day/reload");check(ContractState.get(s).tracked(b.getUuid()).equals(ids[1]),"Tracked contract identity persisted");results.put("restart_cancellation_wallet_and_frozen_target",true);command(1,"trackingProof");command(0,"wait");phase=101;}
   case 101->{if(!ack(1))return;check(read(names[1]+".reply.json").getAsJsonObject("snapshot").get("contract").getAsString().equals(ids[1].toString()),"Real client's HUD restored without board reopen");var mob=s.getOverworld().getEntity(target);b.changeGameMode(GameMode.CREATIVE);b.getAttributeInstance(EntityAttributes.GENERIC_ATTACK_DAMAGE).setBaseValue(1000);b.teleport(s.getOverworld(),mob.getX()-2,mob.getY(),mob.getZ(),-90,0);command(1,"fight","target",target);phase=102;}
   case 102->{if(!ack(1)||hunt(s,1).status()!=ContractInstance.Status.COMPLETED)return;open(b);command(1,"claim","definition",ProceduralHunts.id("katakan"));phase=103;}
   case 103->{if(!ack(1)||hunt(s,1).status()!=ContractInstance.Status.REWARDED)return;check(wallet(b)==paid,"Second independent owner paid after restart");command(1,"replayClaim","definition",ProceduralHunts.id("katakan"));open(a);command(0,"accept","definition",ProceduralHunts.id("ghoul"));phase=104;}
   case 104->{if(!ack(0)||!ack(1))return;check(wallet(b)==paid,"Replay cannot duplicate reward");var active=ContractState.get(s).ownedBy(a.getUuid()).stream().filter(c->c.status()==ContractInstance.Status.ACCEPTED).findFirst().orElseThrow();normal=active.id();check(active.investigation.clues.size()==2,"Normal new hunt prepared");command(0,"cancelPrompt","definition",ProceduralHunts.id("ghoul"),"instance",normal);phase=105;}
   case 105->{if(!ack(0))return;check(ContractState.get(s).find(normal).status()==ContractInstance.Status.ACCEPTED,"Normal cancellation also asks confirmation");command(0,"cancelConfirm");phase=106;}
   case 106->{if(!ack(0))return;check(ContractState.get(s).find(normal).status()==ContractInstance.Status.CANCELLED&&wallet(a)==paid&&wallet(b)==paid,"Normal cancellation and wallets isolated");results.put("normal_gui_cancel_and_multiplayer_reward_replay",true);results.put("complete",true);write("complete.json",results);for(int i=0;i<2;i++)command(i,"stop");phase=999;}
  }
  if(ticks%100==0)write("heartbeat.json",Map.of("phase",phase,"ticks",ticks));
 }catch(Exception e){try{write("server-failure.json",Map.of("phase",phase,"error",e.toString()));}catch(Exception ignored){}phase=999;s.stop(false);}});}
}
